struct Z
{
  float a;
  float b;
};

const int itr = 10;

Z sum(Z z1, Z z2)
{
  Z z3;

  z3.a = z1.a + z2.a;
  z3.b = z1.b + z2.b;

  return z3;
}

Z prod(Z z1, Z z2)
{
  Z z3;

  z3.a = (z1.a * z2.a) - (z1.b * z2.b);
  z3.b = (z1.a * z2.b) + (z2.a * z1.b);

  return z3;
}

Z sqr(Z z_in)
{
return prod(z_in, z_in);
}

float mag(Z z)
{
  return (z.a * z.a) + (z.b * z.b);
}

Z mandelSingleItr(Z z, Z c)
{
  return sum(sqr(z), c);
}

vec3 palette (float t, vec3 a, vec3 b, vec3 c, vec3 d)
{
  return a + b * cos(6.28318f*(c*t + d));
}

vec3 paletteFunc (float t)
{
  vec3 a = vec3(0.5,0.5,0.5);
  vec3 b = vec3(0.5,0.5,0.5);
  vec3 c = vec3(1,1,1);
  //vec3 d = vec3(0.263f, 0.416f, 0.577f);
  //vec3 d = vec3(0.00, 0.33, 0.67);
  vec3 d = vec3(0.0, 0.7, 1.f);

  return palette(t, a, b, c, d);
}

vec3 mandelProc(Z z)
{
  int counter = 0;
  Z c;

  c.a = -0.7 + 0.01*cos(log(iTime+1.f));
  c.b = -0.25 + 0.01*sin(log(iTime+1.f));

  while ((mag(z) < 100.f) && (counter < int(190.f*(1.08f + sin(iTime/5.f)))))
  {
    z = mandelSingleItr(z, c);
    counter++;
  }

  float counter_f = float(counter);
  if (counter > int(190.f*(1.08f + sin(iTime/5.f)))-4) return vec3(0,0,0);
  //else return paletteFunc(((0.49 + (0.02 * sin(iTime/2.f))) * counter_f) + iTime/4.f);
  //else return paletteFunc((1.61803398875 * counter_f) + iTime/4.f);
  else return paletteFunc((0.09 * counter_f) + iTime/4.f);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float iTime2 = pow(2.f, iTime/2.f-4.f);

    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (2.f * fragCoord/(iResolution.xy)) - 1.f;
    uv.x *= iResolution.x/(iResolution.y);
    uv /= 8.f;
    //uv.x -= 0.9f;
    uv.y -= 0.6f;

    //uv /= 2.f;

    Z c[itr];

    for (int i = 0; i < itr; i++)
    {
        c[i].a = uv.x + (/*sin(iTime/300.f)*/0.05 /*float(i)*/ *  sin(float(i)*0.314));
        c[i].b = uv.y + (/*sin(iTime/300.f)*/0.05 /*float(i)*/ *  cos(float(i)*0.314));
    }

    // Output to screen
    for (int i = 0; i < itr; i++)
    {
      fragColor += 0.2 * vec4((1.f - (0.05 * float(i))) * mandelProc(c[i]), 1);
    }
}
